import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.Lq8Lraw_.js";const c=JSON.parse('{"title":"17 rerere：让 Git 记住你的解法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/collaboration/07-rerere.md","filePath":"guide/collaboration/07-rerere.md","lastUpdated":1792671989000}'),l={name:"guide/collaboration/07-rerere.md"};function t(r,s,h,p,d,k){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="_17-rerere-让-git-记住你的解法" tabindex="-1">17 rerere：让 Git 记住你的解法 <a class="header-anchor" href="#_17-rerere-让-git-记住你的解法" aria-label="Permalink to &quot;17 rerere：让 Git 记住你的解法&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>学完本章，你将能够：</p><ul><li>说清 rerere 的名字来源与它解决的问题</li><li>开启 <code>rerere.enabled</code> 与 <code>rerere.autoupdate</code>，观察 Git 自动复用冲突解法</li><li>在长期分支、反复 rebase 的场景中用 rerere 节省重复劳动</li><li>判断哪些冲突 rerere 帮不上忙</li><li>了解团队共享 <code>rr-cache</code> 的收益与风险</li></ul><h2 id="名字就是它的全部含义" tabindex="-1">名字就是它的全部含义 <a class="header-anchor" href="#名字就是它的全部含义" aria-label="Permalink to &quot;名字就是它的全部含义&quot;">​</a></h2><p><strong>rerere = reuse recorded resolution（复用已记录的冲突解法）</strong>。</p><p>默认情况下，同一个冲突你解决一次，下次遇到还得再解决一次。典型场景：</p><ul><li>长期功能分支每周 rebase 一次 <code>main</code>，每次都在同一处冲突；</li><li>同一个 hotfix 要 cherry-pick 到 5 个 release 分支；</li><li>团队成员反复遇到同一段代码的合并冲突。</li></ul><p>rerere 会在你解决冲突时，记录「冲突前长什么样 → 你解决后长什么样」，下次遇到<strong>完全相同的冲突块</strong>时自动套用。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 开启（只需一次）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerere.enabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 可选：自动把解好的文件加入暂存区</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerere.autoupdate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><h2 id="一次完整演示" tabindex="-1">一次完整演示 <a class="header-anchor" href="#一次完整演示" aria-label="Permalink to &quot;一次完整演示&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerere.enabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 第一次遇到冲突，正常解决</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CONFLICT (content): Merge conflict in src/config.ts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 编辑文件，删掉冲突标记</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/config.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-edit</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Recorded resolution for &#39;src/config.ts&#39;.</span></span></code></pre></div><p>注意最后一行 <code>Recorded resolution</code>，说明解法已存入 <code>.git/rr-cache/</code>。</p><p>回退到合并前，再执行一次同样的合并：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD^</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CONFLICT (content): Merge conflict in src/config.ts</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Resolved &#39;src/config.ts&#39; using previous resolution.</span></span></code></pre></div><p>打开文件，冲突标记已经消失，内容与上次解法完全一致。你只需要：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/config.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-edit</span></span></code></pre></div><p>如果开启 <code>rerere.autoupdate</code>，连 <code>git add</code> 都省了，直接 <code>git commit</code>。</p><div class="tip custom-block"><p class="custom-block-title">rebase 场景收益最大</p><p><code>git rebase main</code> 每次都会重放提交，长期分支上同一冲突可能反复出现。开启 rerere 后，第二次开始基本无感。配合第 14 章的交互式 rebase，可以大幅降低维护成本。</p></div><h2 id="查看与清理记录" tabindex="-1">查看与清理记录 <a class="header-anchor" href="#查看与清理记录" aria-label="Permalink to &quot;查看与清理记录&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出已记录的冲突路径</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerere</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看某个冲突的解法差异</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerere</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 忘记记录时的补救：手动标记为已解决</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerere</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 清空所有记录（谨慎，通常不需要）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .git/rr-cache</span></span></code></pre></div><p><code>rr-cache</code> 里存的是冲突块的哈希和对应文件版本，不包含完整仓库内容，体积通常很小。</p><h2 id="团队共享-rr-cache-的取舍" tabindex="-1">团队共享 rr-cache 的取舍 <a class="header-anchor" href="#团队共享-rr-cache-的取舍" aria-label="Permalink to &quot;团队共享 rr-cache 的取舍&quot;">​</a></h2><p><code>rr-cache</code> 位于 <code>.git/</code> 下，默认不随仓库分发。团队可以把它提交到仓库（或通过 CI 缓存同步），让所有人共享解法。</p><p>收益：</p><ul><li>新人遇到历史遗留的反复冲突时，能直接复用老同事的解法；</li><li>大重构期间，多人 rebase 同一分支的冲突处理成本下降。</li></ul><p>风险：</p><ul><li>解法可能<strong>过时</strong>：代码语义变了，旧解法机械套用会引入错误；</li><li>冲突块哈希相同不代表上下文相同，自动套用后仍必须 review；</li><li>把 <code>.git</code> 内部结构纳入版本管理，需要团队对流程有共识。</li></ul><div class="warning custom-block"><p class="custom-block-title">自动复用不等于自动正确</p><p>rerere 只匹配冲突块的文本形态，不理解业务语义。开启 <code>autoupdate</code> 后，错误解法会被自动暂存，<strong>提交前必须 <code>git diff --staged</code> 检查</strong>。</p></div><h2 id="rerere-帮不上忙的情况" tabindex="-1">rerere 帮不上忙的情况 <a class="header-anchor" href="#rerere-帮不上忙的情况" aria-label="Permalink to &quot;rerere 帮不上忙的情况&quot;">​</a></h2><ul><li><strong>语义冲突</strong>：文本不冲突，合并后行为错误——rerere 无从记录。</li><li><strong>冲突块有细微差异</strong>：多一个空格、上下文行不同，哈希就变了，无法命中。</li><li><strong>冲突范围变化</strong>：上次冲突 3 行，这次 5 行，视为不同冲突。</li><li><strong>跨语言的合并策略冲突</strong>：二进制文件、生成代码的冲突需要人工或工具处理。</li></ul><h2 id="与其它工具的配合" tabindex="-1">与其它工具的配合 <a class="header-anchor" href="#与其它工具的配合" aria-label="Permalink to &quot;与其它工具的配合&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 推荐组合：rerere + merge.conflictStyle=diff3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge.conflictStyle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerere.enabled</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rerere.autoupdate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><p><code>diff3</code> 让首次解决时能看到 base，做出更准确的判断；rerere 负责后续复用。两者不冲突。</p><p>如果团队使用 <code>git mergetool</code>，rerere 依然生效——它记录的是最终写入工作区的内容，与解决方式无关。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ol><li><strong>以为开了 rerere 就万事大吉</strong>：它只在<strong>完全相同的冲突块</strong>上生效。</li><li><strong><code>autoupdate</code> 后不检查直接提交</strong>：可能把过时解法提交上线。</li><li><strong>在多个仓库间手动拷贝 <code>rr-cache</code></strong>：路径与冲突哈希可能不匹配，收益有限。</li><li><strong>清理 <code>.git</code> 时误删 <code>rr-cache</code></strong>：解法记录丢失，但不会影响仓库完整性。</li><li><strong>把 rerere 当成冲突预防</strong>：它只是复用解法，减少冲突要靠小提交、勤同步、清晰的分支边界。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>rerere 记录并复用「相同冲突块」的解法，名字即 reuse recorded resolution。</li><li>开启只需 <code>rerere.enabled true</code>，配合 <code>autoupdate</code> 可自动暂存。</li><li>长期分支反复 rebase、同一修复多次 cherry-pick 时收益最大。</li><li>自动复用必须人工 review，语义正确性不能交给工具。</li><li>真正的冲突治理仍是：小步提交、频繁同步、明确的分支职责。</li></ul>`,39)])])}const g=i(l,[["render",t]]);export{c as __pageData,g as default};
